import numpy as np
def f(inp):
    A=np.array(inp); H,W=A.shape
    cr=[r for r in range(H) if len(set(A[r]))==1][0]
    cl=[c for c in range(W) if np.all(A[:,c]==A[cr,0])][0]
    cc=int(A[cr,cl])
    nz=(A!=cc)
    rr,ccz=np.where(nz)
    minr=min(rr); maxr=max(rr); minc=min(ccz); maxc=max(ccz)
    pat=A[minr:maxr+1, minc:maxc+1]
    S={'id':pat,'vflip':pat[::-1],'hflip':pat[:,::-1],'rot180':pat[::-1,::-1]}
    Ho,Wo=H-1,W-1
    out=np.full((Ho,Wo),int(cc))
    def put(dr,dc,S_):
        h,w=S_.shape
        r0,r1=dr,dr+h; c0,c1=dc,dc+w
        if r1<=Ho and c1<=Wo: out[r0:r1,c0:c1]=S_
    locs={'id':(minr,minc),'vflip':(2*cr-maxr,minc),'hflip':(minr,2*cl-maxc),'rot180':(2*cr-maxr,2*cl-maxc)}
    for lab,(lr,lc) in locs.items(): put(lr,lc,S[lab])
    return out.tolist()
